cd /work; { sed -n '/^DROP/,/^);$/p' schema.sql | sed -n '1,200p'; } > /dev/null
cat > solution.sql <<'EOF'
-- Solution: DDL + bulk load + index for target_query.sql
\set ON_ERROR_STOP 1
SET client_min_messages = warning;

-- 1. DDL (exactly as schema.sql)
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS customers CASCADE;

CREATE TABLE customers (
    customer_id   bigint PRIMARY KEY,
    customer_name varchar(120) NOT NULL,
    email         varchar(200) NOT NULL,
    country       varchar(2)   NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE products (
    product_id   bigint PRIMARY KEY,
    product_name varchar(160) NOT NULL,
    category     varchar(60)  NOT NULL,
    unit_price   numeric(10,2) NOT NULL
);

CREATE TABLE orders (
    order_id     bigint PRIMARY KEY,
    customer_id  bigint NOT NULL REFERENCES customers(customer_id),
    order_date   timestamptz NOT NULL,
    status       varchar(20) NOT NULL,
    total_amount numeric(12,2) NOT NULL
);

CREATE TABLE order_items (
    order_item_id bigint PRIMARY KEY,
    order_id      bigint NOT NULL REFERENCES orders(order_id),
    product_id    bigint NOT NULL REFERENCES products(product_id),
    quantity      integer NOT NULL,
    unit_price    numeric(10,2) NOT NULL
);

-- 2. Bulk load (set-based INSERT ... SELECT generate_series, one transaction,
--    secondary indexes created after the load).
BEGIN;
SELECT setseed(0.42);

INSERT INTO customers (customer_id, customer_name, email, country, created_at)
SELECT g, 'Customer ' || g, 'customer' || g || '@example.com',
       (ARRAY['US','GB','DE','FR','JP','BR','IN','CA'])[1 + (g % 8)],
       TIMESTAMPTZ '2024-01-01' + (g % 500) * INTERVAL '1 day'
FROM generate_series(1, 10000) g;

INSERT INTO products (product_id, product_name, category, unit_price)
SELECT g, 'Product ' || g,
       (ARRAY['Electronics','Books','Clothing','Home','Toys','Sports','Grocery','Beauty'])[1 + (g % 8)],
       round((5 + random() * 495)::numeric, 2)
FROM generate_series(1, 1000) g;

-- 100,000 orders; status: COMPLETED 50%, PENDING 20%, CANCELLED 15%, REFUNDED 15%;
-- order_date uniform over 2025-06-01 .. 2026-09-30.
INSERT INTO orders (order_id, customer_id, order_date, status, total_amount)
SELECT g,
       1 + floor(random() * 10000)::bigint,
       TIMESTAMPTZ '2025-06-01' + random() * (TIMESTAMPTZ '2026-10-01' - TIMESTAMPTZ '2025-06-01'),
       CASE WHEN r < 0.50 THEN 'COMPLETED'
            WHEN r < 0.70 THEN 'PENDING'
            WHEN r < 0.85 THEN 'CANCELLED'
            ELSE 'REFUNDED' END,
       0
FROM (SELECT g, random() AS r FROM generate_series(1, 100000) g) s;

-- 1..5 items per order (~300k rows)
INSERT INTO order_items (order_item_id, order_id, product_id, quantity, unit_price)
SELECT row_number() OVER (ORDER BY o.order_id, i), o.order_id, p.product_id,
       q, p.unit_price
FROM (SELECT order_id, 1 + floor(random() * 5)::int AS n FROM orders) o
CROSS JOIN LATERAL generate_series(1, o.n) i
CROSS JOIN LATERAL (SELECT 1 + floor(random() * 5)::int AS q,
                           1 + floor(random() * 1000)::bigint + 0 * i AS pid) x
JOIN products p ON p.product_id = x.pid;

UPDATE orders o SET total_amount = t.s
FROM (SELECT order_id, sum(quantity * unit_price) s FROM order_items GROUP BY order_id) t
WHERE t.order_id = o.order_id;
COMMIT;

-- 3. Indexes
-- Equality column first, range column second; INCLUDE order_id so the orders
-- side can be answered by an index-only scan.
CREATE INDEX orders_status_order_date_idx
    ON orders (status, order_date) INCLUDE (order_id);
-- FK join support for order_items -> orders / products.
CREATE INDEX order_items_order_id_idx   ON order_items (order_id);
CREATE INDEX order_items_product_id_idx ON order_items (product_id);

-- Refresh stats and the visibility map (enables index-only scans).
VACUUM ANALYZE customers;
VACUUM ANALYZE products;
VACUUM ANALYZE orders;
VACUUM ANALYZE order_items;
EOF
psql -q -v ON_ERROR_STOP=1 -f solution.sql && psql -c "ANALYZE" -c "select count(*) from orders" -c "select count(*) from order_items" && psql -c "EXPLAIN ANALYZE $(grep -v '^--' target_query.sql)"

